/**
 * Delayed promise. It is only constructed once the value is accessed.
 * This is useful to avoid unhandled promise rejections when the promise is created
 * but not accessed.
 */
export class DelayedPromise<T> {
  public status: { type: 'pending' } | { type: 'resolved'; value: T } | { type: 'rejected'; error: unknown } = {
    type: 'pending',
  };
  private _promise: Promise<T> | undefined;
  private _resolve: undefined | ((value: T) => void) = undefined;
  private _reject: undefined | ((error: unknown) => void) = undefined;

  get promise(): Promise<T> {
    if (this._promise) {
      return this._promise;
    }

    this._promise = new Promise<T>((resolve, reject) => {
      if (this.status.type === 'resolved') {
        resolve(this.status.value);
        return;
      }
      if (this.status.type === 'rejected') {
        reject(this.status.error);
        return;
      }

      this._resolve = resolve;
      this._reject = reject;
    });

    return this._promise;
  }

  resolve(value: T): void {
    this.status = { type: 'resolved', value };

    if (!this._promise) return;

    if (this._resolve) {
      const resolve = this._resolve;
      this._resolve = undefined;
      resolve(value);
      return;
    }

    // Already settled. A durable stream publishes usage at suspension, then the
    // resumed finish replaces it. Chain onto the promise itself so a later await
    // of the getter sees the latest value, not the provisional one.
    this._promise = this._promise.then(() => value);
  }

  reject(error: unknown): void {
    this.status = { type: 'rejected', error };

    if (this._promise) {
      this._reject?.(error);
    }
  }
}
